static void upgradeMergeMode(HoodieTableConfig tableConfig, Map<ConfigProperty, String> tablePropsToAdd) {
  String payloadClass = tableConfig.getPayloadClass();
  String orderingFields = tableConfig.getOrderingFieldsStr().orElse(null);
  if (isCustomPayloadClass(payloadClass)) {
    // This contains a special case: HoodieMetadataPayload.
    tablePropsToAdd.put(HoodieTableConfig.PAYLOAD_CLASS_NAME, payloadClass);
    tablePropsToAdd.put(HoodieTableConfig.RECORD_MERGE_MODE, RecordMergeMode.CUSTOM.name());
    tablePropsToAdd.put(HoodieTableConfig.RECORD_MERGE_STRATEGY_ID, HoodieRecordMerger.PAYLOAD_BASED_MERGE_STRATEGY_UUID);
  } else if (tableConfig.getTableType() == HoodieTableType.COPY_ON_WRITE) {
    setEventTimeOrCommitTimeBasedOnPayload(payloadClass, tablePropsToAdd);
  } else { // MOR table
    if (StringUtils.nonEmpty(orderingFields)) {
      // This contains a special case: OverwriteWithLatestPayload with preCombine field.
      tablePropsToAdd.put(HoodieTableConfig.PAYLOAD_CLASS_NAME, DefaultHoodieRecordPayload.class.getName());
      tablePropsToAdd.put(HoodieTableConfig.RECORD_MERGE_MODE, RecordMergeMode.EVENT_TIME_ORDERING.name());
      tablePropsToAdd.put(HoodieTableConfig.RECORD_MERGE_STRATEGY_ID, HoodieRecordMerger.EVENT_TIME_BASED_MERGE_STRATEGY_UUID);
    } else {
      setEventTimeOrCommitTimeBasedOnPayload(payloadClass, tablePropsToAdd);
    }
  }
}

private static void setEventTimeOrCommitTimeBasedOnPayload(String payloadClass, Map<ConfigProperty, String> tablePropsToAdd) {
  // DefaultRecordPayload without preCombine Field.
  // This is unlikely to happen.
  if (useDefaultHoodieRecordPayload(payloadClass)) {
    tablePropsToAdd.put(HoodieTableConfig.PAYLOAD_CLASS_NAME, DefaultHoodieRecordPayload.class.getName());
    tablePropsToAdd.put(HoodieTableConfig.RECORD_MERGE_MODE, RecordMergeMode.EVENT_TIME_ORDERING.name());
    tablePropsToAdd.put(HoodieTableConfig.RECORD_MERGE_STRATEGY_ID, HoodieRecordMerger.EVENT_TIME_BASED_MERGE_STRATEGY_UUID);
  } else {
    tablePropsToAdd.put(HoodieTableConfig.PAYLOAD_CLASS_NAME, OverwriteWithLatestAvroPayload.class.getName());
    tablePropsToAdd.put(HoodieTableConfig.RECORD_MERGE_MODE, RecordMergeMode.COMMIT_TIME_ORDERING.name());
    tablePropsToAdd.put(HoodieTableConfig.RECORD_MERGE_STRATEGY_ID, HoodieRecordMerger.COMMIT_TIME_BASED_MERGE_STRATEGY_UUID);
  }
}

static boolean useDefaultHoodieRecordPayload(String payloadClass) {
  return !StringUtils.isNullOrEmpty(payloadClass)
      && payloadClass.equals(DefaultHoodieRecordPayload.class.getName());
}

static boolean isCustomPayloadClass(String payloadClass) {
  return !StringUtils.isNullOrEmpty(payloadClass)
      && !payloadClass.equals(DefaultHoodieRecordPayload.class.getName())
      && !payloadClass.equals(EventTimeAvroPayload.class.getName())
      && !payloadClass.equals(OverwriteWithLatestAvroPayload.class.getName());
}
